 "content": "def transform(grid):
    """Draw the motif associated with each isolated 3 marker."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    markers = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 3]
    for r, c in markers:
        top, left, right, bottom = r - 2, c - 2, c + 2, r + 2
        # The top cap has a 5 center stem and 2-colored side columns.
        for cc in range(left, right + 1):
            if 0 <= top < h and 0 <= cc < w:
                out[top][cc] = 5
        for rr in range(top + 1, r + 2):
            for cc in (left, right):
                if 0 <= rr < h and 0 <= cc < w:
                    out[rr][cc] = 2
        if 0 <= r - 1 < h and 0 <= c < w:
            out[r - 1][c] = 5
        # Horizontal band at the bottom of the motif: 2 outside, 8 under the marker.
        if 0 <= bottom < h:
            for cc in range(w):
                out[bottom][cc] = 8 if left <= cc <= right else 2
    return out
